-- The xx of IFxx, DOWxx, DOUxx and CASxx and its comparison operator.
CREATE OR REPLACE TABLE IACNVCMP (
  XX        CHAR(2)      NOT NULL PRIMARY KEY,
  OPERATOR  VARCHAR(2)   NOT NULL,
  SOURCE    VARCHAR(100) NOT NULL
) RCDFMT IACNVCMPR;

INSERT INTO IACNVCMP (XX, OPERATOR, SOURCE) VALUES
  ('GT', '>', 'SC09-1818 chapter 27, Structured Programming Operations'),
  ('LT', '<', 'SC09-1818 chapter 27, Structured Programming Operations'),
  ('EQ', '=', 'SC09-1818 chapter 27, Structured Programming Operations'),
  ('NE', '<>', 'SC09-1818 chapter 27, Structured Programming Operations'),
  ('GE', '>=', 'SC09-1818 chapter 27, Structured Programming Operations'),
  ('LE', '<=', 'SC09-1818 chapter 27, Structured Programming Operations');

-- The test a resulting indicator stands for ({RES}, {F1}, {F2}).
CREATE OR REPLACE TABLE IACNVRES (
  CODE    VARCHAR(4)   NOT NULL PRIMARY KEY,
  TEST    VARCHAR(100) NOT NULL,
  SOURCE  VARCHAR(100) NOT NULL
) RCDFMT IACNVRESR;

INSERT INTO IACNVRES (CODE, TEST, SOURCE) VALUES
  ('+', '{RES} > 0', 'SC09-1818 Table 20 and chapter 27'),
  ('-', '{RES} < 0', 'SC09-1818 Table 20 and chapter 27'),
  ('Z', '{RES} = 0', 'SC09-1818 Table 20 and chapter 27'),
  ('ZB', '{RES} = 0', 'SC09-1818 Table 20 and chapter 27'),
  ('HI', '{F1} > {F2}', 'SC09-1818 Table 20 and chapter 27'),
  ('LO', '{F1} < {F2}', 'SC09-1818 Table 20 and chapter 27'),
  ('EQ', '{F1} = {F2}', 'SC09-1818 Table 20 and chapter 27'),
  ('NR', 'not %found({F2})', 'SC09-1818 Table 20 and chapter 27'),
  ('ER', '%error', 'SC09-1818 Table 20 and chapter 27'),
  ('EOF', '%eof({F2})', 'SC09-1818 Table 20 and chapter 27'),
  ('BOF', '%eof({F2})', 'SC09-1818 Table 20 and chapter 27');

-- Every indicator name and its free-form name. CYCLE = 'Y': the indicator
-- belongs to the RPG cycle and the line is reported R.
CREATE OR REPLACE TABLE IACNVIND (
  NAME      CHAR(2)      NOT NULL PRIMARY KEY,
  CLASS     VARCHAR(12)  NOT NULL,
  FREEFORM  VARCHAR(10)  NOT NULL,
  CYCLE     CHAR(1)      NOT NULL,
  REASON    VARCHAR(100) NOT NULL,
  SOURCE    VARCHAR(100) NOT NULL
) RCDFMT IACNVINDR;

