-- Settings of the conversion.
CREATE OR REPLACE TABLE IACNVCFG (
  CFGKEY       VARCHAR(30)  NOT NULL PRIMARY KEY,
  CFGVALUE     VARCHAR(200) NOT NULL,
  DESCRIPTION  VARCHAR(200) NOT NULL
) RCDFMT IACNVCFGR;

